1	import Link from "next/link";
2	import { Reveal } from "./Reveal";
3	import { Section, SectionTitle, PageHero } from "./primitives";
4	import { CtaBand } from "./sections";
5	import { PricingGrid, type PlanCard } from "./PricingGrid";
6	import { FaqJsonLd, ProductJsonLd, ProductOffersJsonLd, APP_URL } from "./StructuredData";
7	import { deployHref, type DeployService } from "@/lib/deploy-intent";
8	
9	/**
10	 * Shared shell for high-intent "host X on a VPS" use-case landing pages.
11	 *
12	 * The layout is consistent (premium, converts); the SUBSTANCE — intro prose,
13	 * why-points, deploy steps, FAQ — comes entirely from per-page `content`, so
14	 * every page is genuinely unique (not a thin/doorway template). Real plans feed
15	 * the pricing grid and the Product rich-result. Each page is a server component
16	 * that fetches `db.plan` and passes it here.
17	 */
18	export type UseCaseContent = {
19	  eyebrow: string;
20	  /** H1 lead-in (rendered plain) + the gradient highlight word/phrase. */
21	  title: string;
22	  highlight: string;
23	  sub: string;
24	  /** 1–3 short paragraphs of unique, specific prose. */
25	  intro: string[];
26	  /** Section title for the value props, e.g. "Built for Minecraft servers". */
27	  whyTitle: string;
28	  why: { title: string; body: string }[];
29	  /** 3–5 concrete steps to deploy X on the server. */
30	  steps: { title: string; body: string }[];
31	  /** Optional sizing hint shown above the plans. */
32	  specNote?: string;
33	  faq: { q: string; a: string }[];
34	  /** Internal links to related pages (crawl + authority flow). */
35	  related?: { label: string; href: string }[];
36	};
37	
38	export function UseCaseLanding({
39	  content,
40	  plans,
41	  service = "vps",
42	  gameFamily,
43	  productName,
44	  pageUrl,
45	}: {
46	  content: UseCaseContent;
47	  plans: PlanCard[];
48	  /**
49	   * Which product these `plans` deploy as. Defaults to "vps" — unchanged
50	   * behavior for every pre-existing (location × service) page, which always
51	   * passes real `Plan` rows. Pass `service="game"` with `gameFamily` for a
52	   * game-family landing page (lib/marketing/gameLocationLandings.ts) whose
53	   * `plans` are `GamePlan` rows mapped to `PlanCard` — this swaps both the
54	   * deploy links (gameFamily + gamePlanId, not a VPS planId) and the
55	   * Product rich-result (a game-specific `ProductOffersJsonLd`, not the
56	   * generic "Nxeon Cloud VPS" `ProductJsonLd`).
57	   */
58	  service?: DeployService;
59	  gameFamily?: string;
60	  /** Product name for the game-service JSON-LD, e.g. "Nxeon Minecraft Server Hosting". */
61	  productName?: string;
62	  /** Canonical URL for the game-service JSON-LD's `url` field. */
63	  pageUrl?: string;
64	}) {
65	  const isGame = service === "game";
66	  const heroHref = isGame
67	    ? deployHref({ service: "game", gameFamily, gamePlanId: plans[0]?.id })
68	    : deployHref({ service: "vps", planId: plans[0]?.id });
69	
70	  return (
71	    <>
72	      <FaqJsonLd items={content.faq} />
73	      {plans.length > 0 &&
74	        (isGame ? (
75	          <ProductOffersJsonLd
76	            name={productName ?? "Nxeon Game Server Hosting"}
77	            description={content.sub}
78	            url={pageUrl ?? APP_URL}
79	            offers={plans.map((p) => ({ name: p.name, price: p.priceCents / 100 }))}
80	          />
81	        ) : (
82	          <ProductJsonLd plans={plans} />
83	        ))}
84	
85	      <PageHero
86	        eyebrow={content.eyebrow}
87	        title={content.title}
88	        highlight={content.highlight}
89	        sub={content.sub}
90	        primary={{ label: "Deploy now", href: heroHref }}
91	        secondary={{ label: "See pricing", href: "#pricing" }}
92	      />
93	
94	      {/* Intro prose */}
95	      <Section tone="base" size="md">
96	        <div className="mx-auto max-w-3xl space-y-4 text-[15px] leading-relaxed text-slate-300">
97	          {content.intro.map((p, i) => (
98	            <Reveal as="p" key={i} delay={i * 60}>
99	              {p}
100	            </Reveal>
101	          ))}
102	        </div>
103	      </Section>
104	
105	      {/* Why Nxeon for X */}
106	      <Section tone="panel" size="md">
107	        <SectionTitle eyebrow="Why Nxeon" title={content.whyTitle} />
108	        <div className="mt-10 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
109	          {content.why.map((w, i) => (
110	            <Reveal key={w.title} delay={i * 60} className="card">
111	              <h3 className="text-base font-semibold text-white">{w.title}</h3>
112	              <p className="mt-2 text-sm leading-relaxed text-slate-400">{w.body}</p>
113	            </Reveal>
114	          ))}
115	        </div>
116	      </Section>
117	
118	      {/* Deploy steps */}
119	      <Section tone="base" size="md">
120	        <SectionTitle eyebrow="Get started" title="Up and running in minutes" />
121	        <ol className="mx-auto mt-10 max-w-3xl space-y-3">
122	          {content.steps.map((s, i) => (
123	            <Reveal as="li" key={s.title} delay={i * 60} className="card flex gap-4">
124	              <span className="flex h-8 w-8 flex-none items-center justify-center rounded-lg bg-brand-500/20 text-sm font-bold text-brand-200">
125	                {i + 1}
126	              </span>
127	              <div>
128	                <h3 className="text-sm font-semibold text-white">{s.title}</h3>
129	                <p className="mt-1 text-sm leading-relaxed text-slate-400">{s.body}</p>
130	              </div>
131	            </Reveal>
132	          ))}
133	        </ol>
134	      </Section>
135	
136	      {/* Real plans */}
137	      {plans.length > 0 && (
138	        <Section tone="panel" size="lg" id="pricing">
139	          <SectionTitle eyebrow="Plans" title="Pick your size" sub={content.specNote} />
140	          <Reveal className="mt-10">
141	            <PricingGrid plans={plans} service={service} gameFamily={gameFamily} />
142	          </Reveal>
143	        </Section>
144	      )}
145	
146	      {/* FAQ */}
147	      <Section tone="base" size="md">
148	        <SectionTitle eyebrow="FAQ" title="Questions, answered" />
149	        <div className="mx-auto mt-10 max-w-3xl space-y-3">
150	          {content.faq.map((f) => (
151	            <details key={f.q} className="card group">
152	              <summary className="cursor-pointer list-none font-medium text-white marker:content-none">
153	                <span className="flex items-center justify-between gap-4">
154	                  {f.q}
155	                  <span className="text-slate-500 transition-transform group-open:rotate-45">+</span>
156	                </span>
157	              </summary>
158	              <p className="mt-3 text-sm leading-relaxed text-slate-400">{f.a}</p>
159	            </details>
160	          ))}
161	        </div>
162	      </Section>
163	
164	      {content.related && content.related.length > 0 && (
165	        <Section tone="base" size="sm">
166	          <div className="mx-auto flex max-w-3xl flex-wrap items-center justify-center gap-2">
167	            <span className="text-xs font-semibold uppercase tracking-wider text-slate-500">Related</span>
168	            {content.related.map((r) => (
169	              <Link
170	                key={r.href}
171	                href={r.href}
172	                className="rounded-full border border-white/10 bg-white/[0.03] px-3 py-1 text-sm text-slate-300 transition-colors hover:border-white/20 hover:text-white"
173	              >
174	                {r.label}
175	              </Link>
176	            ))}
177	          </div>
178	        </Section>
179	      )}
180	
181	      <Section tone="deep" size="lg">
182	        <CtaBand />
183	      </Section>
184	    </>
185	  );
186	}
