1	"use client";
2	
3	import { useState } from "react";
4	import Link from "next/link";
5	import { IconCheck } from "./icons";
6	import { planTip, planAudience } from "./planTips";
7	import { termPriceCents, ANNUAL_TERM_MONTHS, vpsEffectiveMonthly } from "@/lib/billing-terms";
8	import { planIntroMonthlyCents } from "@/lib/intro-pricing";
9	import { useDisplayMoney } from "@/components/currency/CurrencyContext";
10	import { deployHref, type DeployService } from "@/lib/deploy-intent";
11	
12	export type PlanCard = {
13	  id: string;
14	  name: string;
15	  cpuCores: number;
16	  ramMB: number;
17	  diskGB: number;
18	  bandwidthTB: number;
19	  priceCents: number;
20	  storageTier: string;
21	  /**
22	   * LOW introductory MONTHLY price (cents) for the first term — the plan
23	   * RENEWS at `priceCents`. Optional: most callers pass a raw `db.plan` row
24	   * straight through (it carries `introPriceCents` at runtime even though this
25	   * narrower display type doesn't declare it), in which case `planIntroMonthlyCents`
26	   * reads it directly and this field is never needed. Set it explicitly only when
27	   * the caller built a plain object that dropped the original DB row.
28	   */
29	  introMonthlyCents?: number | null;
30	  /**
31	   * Player-slot count — GamePlan rows only (a `db.gamePlan` row mapped to this
32	   * shape by its caller). Shown as a headline feature instead of the generic
33	   * vCPU/RAM/disk framing when `service="game"`, since "slots" is the number a
34	   * game-hosting shopper actually cares about.
35	   */
36	  slots?: number | null;
37	};
38	
39	function planFeatures(p: PlanCard, service: DeployService): string[] {
40	  const disk = p.storageTier === "hdd" ? "HDD storage" : "NVMe SSD storage";
41	  const isGame = service === "game";
42	  return [
43	    ...(isGame && p.slots ? [`${p.slots} player slots`] : []),
44	    `${p.cpuCores} vCPU core${p.cpuCores > 1 ? "s" : ""}`,
45	    `${(p.ramMB / 1024).toFixed(p.ramMB % 1024 ? 1 : 0)} GB RAM`,
46	    `${p.diskGB} GB ${disk}`,
47	    `${p.bandwidthTB} TB bandwidth`,
48	    isGame ? "Full file access (FTP)" : "Full root access",
49	    "Free DDoS protection",
50	  ];
51	}
52	
53	/**
54	 * `service`/`gameFamily`: which product these plans deploy as. Defaults to
55	 * "vps" (unchanged behavior for every existing caller — VPS `Plan` rows
56	 * deployed via `?product=vps&plan=<Plan.id>`). Pass `service="game"` with
57	 * `gameFamily` when `plans` are `GamePlan` rows mapped to this shape (see
58	 * lib/marketing/gameLocationLandings.ts) so each card's "Deploy now" link
59	 * carries `gameFamily` + `gamePlanId` instead of misrouting a GamePlan's id
60	 * through the VPS `plan` param.
61	 */
62	export function PricingGrid({
63	  plans,
64	  annualPct = 0,
65	  service = "vps",
66	  gameFamily,
67	}: {
68	  plans: PlanCard[];
69	  annualPct?: number;
70	  service?: DeployService;
71	  gameFamily?: string;
72	}) {
73	  // Prices are USD-cents in the DB; `money` converts them to the visitor's display
74	  // currency (geo/manual) for rendering only — checkout still charges the USD amount.
75	  const money = useDisplayMoney();
76	  // Billing toggle — Annual is on by default when it's a real discount, so the
77	  // headline price shows the better-value figure first. Switching to Monthly shows
78	  // the undiscounted monthly price. Every figure is DB-fed through termPriceCents,
79	  // the SAME formula checkout charges — displayed === charged.
80	  const annualAvailable = annualPct > 0;
81	  const [annual, setAnnual] = useState(true);
82	  const showAnnual = annual && annualAvailable;
83	
84	  // Highlight the middle plan (by position) as "Most popular"; the top (most
85	  // expensive) plan gets a "Best value / most resources" anchor so the mid tier
86	  // reads as the smart buy.
87	  const popularIdx = plans.length ? Math.floor((plans.length - 1) / 2) : -1;
88	  const topIdx = plans.length >= 3 ? plans.length - 1 : -1;
89	  // The footer "From $X" claim leads with the lowest REAL price — the intro rate
90	  // where one is configured, same as every plan card above it.
91	  const fromCents = plans.length
92	    ? Math.min(...plans.map((p) => p.introMonthlyCents ?? planIntroMonthlyCents(p) ?? p.priceCents))
93	    : 0;
94	  const topCents = plans.length ? Math.max(...plans.map((p) => p.priceCents)) : 0;
95	
96	  if (plans.length === 0) {
97	    return (
98	      <div className="card text-center text-slate-400">
99	        Plans are being provisioned. Please check back shortly.
100	      </div>
101	    );
102	  }
103	
104	  // No promo banner here: first-month-free is a Shared Web Hosting offer only
105	  // (see lib/promo-redemption.ts firstMonthFreeAppliesTo). VPS bills the regular
106	  // price from month one — the price shown IS what checkout charges.
107	
108	  return (
109	    <div>
110	      {annualAvailable && (
111	        <div className="mb-8 flex flex-col items-center gap-2">
112	          <div className="inline-flex items-center rounded-full border border-white/10 bg-navy-900/70 p-1 backdrop-blur">
113	            <button
114	              type="button"
115	              aria-pressed={!annual}
116	              onClick={() => setAnnual(false)}
117	              className={`rounded-full px-5 py-1.5 text-sm font-semibold transition-colors ${
118	                !annual ? "bg-white/10 text-white" : "text-slate-400 hover:text-white"
119	              }`}
120	            >
121	              Monthly
122	            </button>
123	            <button
124	              type="button"
125	              aria-pressed={annual}
126	              onClick={() => setAnnual(true)}
127	              className={`flex items-center gap-2 rounded-full px-5 py-1.5 text-sm font-semibold transition-colors ${
128	                annual ? "bg-gradient-to-r from-accent-blue to-brand-500 text-white shadow" : "text-slate-400 hover:text-white"
129	              }`}
130	            >
131	              Annual
132	              <span className={`rounded-full px-1.5 py-0.5 text-[10px] font-bold ${annual ? "bg-white/20 text-white" : "bg-emerald-500/15 text-emerald-300"}`}>
133	                –{annualPct}%
134	              </span>
135	            </button>
136	          </div>
137	          <p className="text-xs text-slate-500">
138	            {showAnnual ? "Billed yearly · cancel anytime" : "Billed monthly · switch to annual to save"}
139	          </p>
140	        </div>
141	      )}
142	      <div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
143	        {plans.map((p, i) => {
144	          const popular = i === popularIdx;
145	          const topTier = i === topIdx;
146	          const regular = p.priceCents;
147	          // Effective $/mo on the annual term — DB-fed via the shared term formula,
148	          // the same one checkout charges. Only shown when annual is a real discount.
149	          const annualPerMo = annualAvailable ? Math.round(termPriceCents(regular, ANNUAL_TERM_MONTHS, annualPct) / ANNUAL_TERM_MONTHS) : 0;
150	          const annualTotal = annualAvailable ? termPriceCents(regular, ANNUAL_TERM_MONTHS, annualPct) : 0;
151	          const bigCents = showAnnual ? annualPerMo : regular;
152	          // Optional LOW intro price for the first term — `p` is usually a raw
153	          // `db.plan` row (Prisma) even though this narrower `PlanCard` type doesn't
154	          // declare `introPriceCents`, so `planIntroMonthlyCents` reads it straight off
155	          // the object; `p.introMonthlyCents` covers callers that built a plain object
156	          // instead. Run through the SAME `vpsEffectiveMonthly` formula as the regular
157	          // price above so an annual intro term is discounted consistently, not just
158	          // the flat monthly figure. The regular renewal price is always shown
159	          // alongside it — never a hidden teaser jump.
160	          const introMonthlyCents = p.introMonthlyCents ?? planIntroMonthlyCents(p);
161	          const introEffective =
162	            introMonthlyCents != null
163	              ? vpsEffectiveMonthly(introMonthlyCents, showAnnual ? ANNUAL_TERM_MONTHS : 1, annualPct)
164	              : null;
165	          const hasIntro = introEffective != null && introEffective < bigCents;
166	          const shownCents = hasIntro ? introEffective! : bigCents;
167	          // This card's exact plan + the term the toggle above is currently
168	          // showing — carried onto the wizard instead of a flat "/register"
169	          // that discarded which plan/term the customer had just picked.
170	          const deployUrl =
171	            service === "game"
172	              ? deployHref({ service: "game", gameFamily, gamePlanId: p.id, termMonths: showAnnual ? ANNUAL_TERM_MONTHS : 1 })
173	              : deployHref({ service: "vps", planId: p.id, termMonths: showAnnual ? ANNUAL_TERM_MONTHS : 1 });
174	          return (
175	          <div
176	            key={p.id}
177	            className={`group relative flex flex-col rounded-2xl border p-6 backdrop-blur-md transition-all duration-300 hover:-translate-y-1.5 ${
178	              popular
179	                ? "border-brand-500/40 bg-navy-850/80 glow-brand"
180	                : "border-white/[0.06] bg-navy-900/70 hover:border-brand-500/30 hover:bg-navy-850/70 hover:shadow-[0_0_40px_-10px_rgb(111_71_245_/_0.4)]"
181	            }`}
182	          >
183	            {popular && (
184	              <span className="absolute -top-3 left-1/2 -translate-x-1/2 rounded-full bg-gradient-to-r from-accent-blue to-brand-500 px-3 py-1 text-[11px] font-semibold uppercase tracking-wider text-white shadow-lg">
185	                Most popular
186	              </span>
187	            )}
188	            {topTier && !popular && (
189	              <span className="absolute -top-3 right-4 rounded-full border border-white/10 bg-navy-950 px-2.5 py-1 text-[10px] font-semibold uppercase tracking-wider text-slate-300 shadow-lg">
190	                Best value
191	              </span>
192	            )}
193	            <div className="flex items-center justify-between">
194	              <h3 className="text-base font-semibold text-white">{p.name}</h3>
195	              <span className="rounded-full border border-brand-500/30 bg-brand-500/10 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wider text-brand-300">
196	                {topTier ? "Most resources" : planAudience(p)}
197	              </span>
198	            </div>
199	            <div className="mt-3">
200	              <div className="flex items-end gap-1">
201	                <span className="text-4xl font-bold tracking-tight">{money(shownCents)}</span>
202	                <span className="mb-1 text-sm text-slate-400">/mo</span>
203	                {hasIntro && (
204	                  <span className="ml-2 mb-1 text-sm text-slate-500 line-through">{money(bigCents)}</span>
205	                )}
206	              </div>
207	              {hasIntro ? (
208	                <p className="mt-1 text-[11px] leading-snug text-slate-500">
209	                  Intro price for your first {showAnnual ? "term" : "month"}, then {money(bigCents)}/mo — renews at the regular price
210	                </p>
211	              ) : showAnnual ? (
212	                <p className="mt-1 text-[11px] leading-snug text-emerald-300">
213	                  {money(annualTotal)} billed yearly — save {annualPct}% vs {money(regular)}/mo
214	                </p>
215	              ) : annualAvailable ? (
216	                <p className="mt-1 text-[11px] leading-snug text-slate-500">
217	                  or {money(annualPerMo)}/mo billed annually — save {annualPct}%
218	                </p>
219	              ) : (
220	                <p className="mt-1 text-[11px] leading-snug text-slate-500">
221	                  Billed monthly. Cancel anytime.
222	                </p>
223	              )}
224	            </div>
225	            <div className="mt-4 flex items-start gap-2 rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
226	              <span className="mt-0.5 text-brand-300" aria-hidden>
227	                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
228	                  <path d="M9 18h6M10 21h4M12 2a7 7 0 0 0-4 12.7c.6.5 1 1.3 1 2.1h6c0-.8.4-1.6 1-2.1A7 7 0 0 0 12 2z" />
229	                </svg>
230	              </span>
231	              <p className="text-[12px] leading-snug text-slate-300">
232	                <span className="font-semibold text-slate-200">Great for: </span>
233	                {planTip(p)}
234	              </p>
235	            </div>
236	            <ul className="mt-5 flex-1 space-y-3 text-sm">
237	              {planFeatures(p, service).map((f) => (
238	                <li key={f} className="flex items-center gap-2.5 text-slate-300">
239	                  <span className="flex h-4.5 w-4.5 shrink-0 items-center justify-center rounded-full bg-brand-500/15 text-brand-300">
240	                    <IconCheck size={12} />
241	                  </span>
242	                  {f}
243	                </li>
244	              ))}
245	            </ul>
246	            <Link
247	              href={deployUrl}
248	              className={`mt-7 w-full ${popular ? "btn-deploy" : "btn-secondary"}`}
249	            >
250	              Deploy now
251	            </Link>
252	          </div>
253	          );
254	        })}
255	      </div>
256	      <p className="mt-6 text-center text-sm text-slate-500">
257	        From <span className="font-semibold text-slate-300">{money(fromCents)}</span> to{" "}
258	        <span className="font-semibold text-slate-300">{money(topCents)}/mo</span> — every tier gets the same platform, root access and protection; you only choose the horsepower.
259	        {annualPct > 0 && (
260	          <>
261	            {" "}Prefer to pay yearly?{" "}
262	            <span className="font-semibold text-emerald-300">Annual billing saves {annualPct}%</span> — choose your term in the deploy wizard.
263	          </>
264	        )}
265	      </p>
266	    </div>
267	  );
268	}
