1	/**
2	 * Smart, spec-derived guidance for a plan. Given a plan's resources, returns a
3	 * short "great for…" line so visitors can self-select the right box at a glance.
4	 * Pure function — safe on the server and the client.
5	 */
6	
7	export type PlanLike = {
8	  cpuCores: number;
9	  ramMB: number;
10	  diskGB: number;
11	};
12	
13	/** One-line "great for…" recommendation derived from a plan's RAM (and cores). */
14	export function planTip(plan: PlanLike): string {
15	  const ram = plan.ramMB;
16	  if (ram <= 2048) return "Personal sites, dev/staging, bots, VPNs";
17	  if (ram <= 4096) return "WordPress & WooCommerce, small game servers, CI runners";
18	  if (ram <= 8192) return "Busy sites, databases, Docker stacks, small multiplayer servers";
19	  return "High-traffic apps, big databases, multiple sites, heavy workloads";
20	}
21	
22	/** A tighter one/two-word audience label, handy for badges. */
23	export function planAudience(plan: PlanLike): string {
24	  const ram = plan.ramMB;
25	  if (ram <= 2048) return "Starter";
26	  if (ram <= 4096) return "Growth";
27	  if (ram <= 8192) return "Scale";
28	  return "Power";
29	}
