1	"use client";
2	
3	import { useState } from "react";
4	
5	/**
6	 * Country flag image, keyed by raw ISO-3166 alpha-2 code (unlike
7	 * CurrencySwitcher's private Flag, which is keyed by currency code). Falls
8	 * back to a neutral placeholder chip on a missing/failed image rather than
9	 * relying on emoji regional-indicator rendering, which several platforms
10	 * (notably Windows) don't render as flags at all.
