function TpsGraph({ accent, active, reduced }: { accent: string; active: boolean; reduced: boolean }) {
  const pts = [19.9, 20, 19.8, 20, 20, 19.7, 20, 19.9, 20, 20, 19.8, 20];
  const w = 220;
  const h = 46;
  const min = 19.5;
  const max = 20.2;
  const step = w / (pts.length - 1);
  const coords = pts.map((v, i) => {
    const x = i * step;
    const y = h - ((v - min) / (max - min)) * h;
    return [x, y] as const;
  });
  const line = coords.map(([x, y], i) => `${i === 0 ? "M" : "L"}${x.toFixed(1)} ${y.toFixed(1)}`).join(" ");
  const area = `${line} L${w} ${h} L0 ${h} Z`;
  const [ex, ey] = coords[coords.length - 1];
  return (
    <svg viewBox={`0 0 ${w} ${h}`} className="h-[46px] w-full" preserveAspectRatio="none" aria-hidden>
      <defs>
        <linearGradient id="pv-cmb-tps-fill" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor={accent} stopOpacity="0.35" />
          <stop offset="100%" stopColor={accent} stopOpacity="0" />
        </linearGradient>
      </defs>
      <path d={area} fill="url(#pv-cmb-tps-fill)" />
      <path
        d={line}
        fill="none"
        stroke={accent}
        strokeWidth="1.6"
        strokeLinecap="round"
        strokeLinejoin="round"
        className={reduced || !active ? "" : "pv-draw"}
      />
      <circle cx={ex} cy={ey} r="3" fill={accent} className={reduced ? "" : "motion-safe:animate-pulse-dot"} />
